export interface AgentHierarchyTreeProps {
  // Core
  agents: AgentNode[];
  viewMode?: 'tree' | 'graph';
  theme?: 'light' | 'dark';

  // Event handlers
  onAgentSelect?: (agentId: string) => void;
  onAgentHover?: (agentId: string | null) => void;

  // Tree view
  showMetrics?: boolean;
  filterByLevel?: number[];
  filterByState?: AgentState[];
  searchQuery?: string;
  sortStrategy?: SortStrategy;
  maxHeight?: number;
  maxDepth?: number;

  // Graph view
  width?: number;
  height?: number;
  enableZoom?: boolean;
  enableAnimation?: boolean;
  enableExport?: boolean;
  updateInterval?: number;

  // Advanced
  className?: string;
  customIcons?: Partial<IconMapping>;
  customColors?: Partial<ColorScheme>;
}

component_api.props_interface:
export interface StatusMonitorProps {
  // Data
  statuses: Record<string, AgentStatus>;

  // Callbacks
  onAgentSelect?: (agentId: string) => void;
  onRefresh?: (agentId?: string) => Promise<void>;
  onIntervention?: (action: InterventionAction) => Promise<void>;

  // Display
  maxCardsPerRow?: 1 | 2 | 3 | 4;
  showMetrics?: boolean;
  showInterventionControls?: boolean;
  showErrorsOnly?: boolean;
  theme?: 'light' | 'dark';

  // Filtering
  filterByState?: AgentState[];
  sortBy?: 'name' | 'status' | 'health' | 'performance';

  // Real-time
  autoRefresh?: boolean;
  refreshInterval?: number;
  websocketUrl?: string;
  enableRealTimeUpdates?: boolean;

  // Advanced
  className?: string;
  customCardRenderer?: (status: AgentStatus) => ReactNode;
}

export interface PerformanceChartsProps {
  // Data
  systemMetrics: PerformanceMetrics[];
  agentMetrics?: AgentPerformanceData[];

  // Chart selection
  defaultChartType?: 'line' | 'bar' | 'gauge' | 'mixed';
  availableCharts?: ChartType[];

  // Display
  width?: number | string;
  height?: number | string;
  theme?: 'light' | 'dark';
  showGrid?: boolean;
  showLegend?: boolean;
  showTooltips?: boolean;

  // Time range
  timeRange?: '5m' | '15m' | '1h' | '6h' | '24h' | '7d' | '30d';
  onTimeRangeChange?: (range: TimeRange) => void;

  // Real-time
  realTimeUpdates?: boolean;
  updateInterval?: number;

  // Features
  enableExport?: boolean;
  enableFullscreen?: boolean;
  enableAnimation?: boolean;

  // Advanced
  className?: string;
  customColors?: Partial<ColorScheme>;
  onExport?: (format: 'png' | 'csv' | 'json') => void;
}

export interface EventTimelineProps {
  // Data
  events: AgentLifecycleEvent[];

  // Callbacks
  onEventSelect?: (eventId: string) => void;
  onEventHover?: (eventId: string | null) => void;
  onExport?: (events: TimelineEvent[], format: 'json' | 'csv') => void;

  // Display
  maxEvents?: number;
  showDetails?: boolean;
  showFilters?: boolean;
  showStats?: boolean;
  theme?: 'light' | 'dark';

  // Filtering
  filterByEventType?: LifecycleEventType[];
  filterByAgent?: string[];
  filterBySeverity?: ('info' | 'warning' | 'error' | 'success')[];
  timeRange?: { start: Date; end: Date };
  searchQuery?: string;

  // Real-time
  autoRefresh?: boolean;
  refreshInterval?: number;
  enableRealTimeStreaming?: boolean;

  // Performance
  enableVirtualization?: boolean;
  virtualScrollHeight?: number;

  // Advanced
  className?: string;
  customEventRenderer?: (event: TimelineEvent) => ReactNode;
  customIconMapping?: Partial<EventIconMapping>;
}
